class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Calculate final position using the formula: row * n + col
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[x] represents number of ways to assign values to previous positions
        # such that the last value is x
        dp = {}

        # Base case: position 0
        for x in range(nums[0] + 1):
            dp[x] = 1

        # Process each subsequent position
        for i in range(1, n):
            new_dp = {}

            # For each possible value of arr1[i]
            for x in range(nums[i] + 1):
                total_ways = 0

                # For each possible value of arr1[i-1]
                for prev_x, ways in dp.items():
                    # Check if we can have arr1[i] = x given arr1[i-1] = prev_x
                    # Non-decreasing: x >= prev_x
                    # Non-increasing constraint: nums[i-1] - prev_x >= nums[i] - x
                    # which simplifies to: x >= nums[i] - nums[i-1] + prev_x

                    if x >= prev_x and x >= nums[i] - nums[i-1] + prev_x:
                        total_ways = (total_ways + ways) % MOD

                if total_ways > 0:
                    new_dp[x] = total_ways

            dp = new_dp

        # Sum all possibilities for the final position
        result = 0
        for ways in dp.values():
            result = (result + ways) % MOD

        return result

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store color counts for each player
        player_color_count = {}

        # Initialize for all players
        for i in range(n):
            player_color_count[i] = {}

        # Count balls picked by each player for each color
        for player, color in pick:
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count winning players
        winners = 0

        # Check each player from 0 to n-1
        for i in range(n):
            # Find the maximum number of balls of the same color picked by player i
            max_balls = 0
            if player_color_count[i]:  # if player has picked any balls
                max_balls = max(player_color_count[i].values())

            # Player i wins if they have at least (i+1) balls of the same color
            if max_balls >= i + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate flips needed for all columns to be palindromic
        cols_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return minimum of the two options
        return min(rows_flips, cols_flips)

