    points = []
    for _ in range(N):
        x, y = map(int, input().split())
        points.append((x, y))

    if N == 1:
        return 2 * D * D + 2 * D + 1

    # Get all x and y coordinates
    x_coords = [p[0] for p in points]
    y_coords = [p[1] for p in points]

    # Sort coordinates
    x_coords.sort()
    y_coords.sort()

    # Precompute prefix sums for efficient sum of absolute deviations
    n = len(x_coords)
    prefix_x = [0] * (n + 1)
    for i in range(n):
        prefix_x[i + 1] = prefix_x[i] + x_coords[i]

    prefix_y = [0] * (n + 1)
    for i in range(n):
        prefix_y[i + 1] = prefix_y[i] + y_coords[i]

    # Function to compute sum of |x - x_i| for all i
    def sum_abs_x(x):
        # Binary search for insertion point
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if x_coords[mid] <= x:
                left = mid + 1
            else:
                right = mid

        idx = left - 1

        if idx == -1:
            return sum(x_coords[i] - x for i in range(n))
        elif idx == n - 1:
            return sum(x - x_coords[i] for i in range(n))
        else:
            sum_left = (idx + 1) * x - prefix_x[idx + 1]
            sum_right = (prefix_x[n] - prefix_x[idx + 1]) - x * (n - idx - 1)
            return sum_left + sum_right

    # Function to compute sum of |y - y_i| for all i
    def sum_abs_y(y):
