            return sum(y_coords[i] - y for i in range(n))
        elif idx == n - 1:
            return sum(y - y_coords[i] for i in range(n))
        else:
            sum_left = (idx + 1) * y - prefix_y[idx + 1]
            sum_right = (prefix_y[n] - prefix_y[idx + 1]) - y * (n - idx - 1)
            return sum_left + sum_right

    # Find the range of x and y to check
    min_x, max_x = min(x_coords), max(x_coords)
    min_y, max_y = min(y_coords), max(y_coords)

    # We'll check x values from min_x - D to max_x + D
    # But we can skip x values where sum_abs_x(x) > D
    x_range = range(min_x - D, max_x + D + 1)

    # Count valid pairs
